def apply(doc_id: str) -> None:
    sp = _cert_dir(doc_id) / doc_id / "script.json"
    if not sp.exists():
        print(f"[skip] {doc_id}: script.json 없음 ({sp})")
        return
    want = SUMMARIES.get(doc_id, {})
    if not want:
        print(f"[skip] {doc_id}: SUMMARIES 항목 없음")
        return
    doc = json.loads(sp.read_text(encoding="utf-8"))
    seg_ids = {s["id"] for s in doc["segments"]}
    applied = []
    for s in doc["segments"]:
        if s["id"] in want:
            s["audioSummary"] = want[s["id"]]
            applied.append(s["id"])
    missing = [k for k in want if k not in seg_ids]
    sp.write_text(
        json.dumps(doc, ensure_ascii=False, indent=2) + "\n", encoding="utf-8"
    )
    msg = f"[apply] {doc_id}: applied {applied}"
    if missing:
        msg += f"  !! MISSING(스크립트 id가 script.json에 없음) {missing}"
    print(msg)


def _self_test() -> None:
    """cert 경로 파생 회귀 가드: doc_id 접두어 → assets/audio/<cert>."""
    for doc_id, cert in {"clf-t1-2": "clf", "saa-t1-1": "saa",
                         "soa-t2-3": "soa"}.items():
        d = _cert_dir(doc_id)
        assert d == BASE / "assets" / "audio" / cert, f"{doc_id} → {d}"
        assert d.name == cert, f"{doc_id} 접두어 파생 실패: {d.name}"
    print("apply_audio_summary self-test OK")


if __name__ == "__main__":
    if "--self-test" in sys.argv[1:]:
        _self_test()
    else:
        ids = [a for a in sys.argv[1:] if not a.startswith("-")] or list(SUMMARIES)
        for d in ids:
            apply(d)
